import json, time, sys, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from collections import Counter
BASE = "http://localhost:8080"
tok = [None]
log = Counter()
def new_token():
    with urllib.request.urlopen(urllib.request.Request(BASE+"/token", method="POST", data=b"")) as r:
        tok[0] = json.load(r)["token"]; log["tokens"] += 1
def get(path):
    for attempt in range(200):
        if tok[0] is None: new_token()
        req = urllib.request.Request(BASE+path, headers={"Authorization": "Bearer "+tok[0]})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read()
                try: return json.loads(body)
                except Exception: log["bad_json"] += 1; continue
        except urllib.error.HTTPError as e:
            log[f"http_{e.code}"] += 1
            if e.code == 401 or e.code == 403: tok[0] = None; continue
            if e.code == 404: return None
            if e.code == 429:
                ra = e.headers.get("Retry-After") or "1"
                time.sleep(float(ra) + 0.1); continue
            time.sleep(0.5); continue
        except Exception as e:
            log["exc_"+type(e).__name__] += 1; time.sleep(0.5); continue
    raise SystemExit("gave up on "+path)

pages = {}
first = get("/orders?page=1"); pages[1] = first
total_pages = first["total_pages"]
p = 2
while p <= total_pages:
    d = get(f"/orders?page={p}")
    if not isinstance(d, dict) or "items" not in d or d.get("page") != p:
        log["bad_page_payload"] += 1; continue
    pages[p] = d
    if d["total_pages"] != total_pages: log["total_pages_changed"] += 1; total_pages = d["total_pages"]
    p += 1
assert pages[total_pages]["next"] is None, pages[total_pages]["next"]
for q in range(1, total_pages):
    assert pages[q]["next"] is not None
orders, dups, conflicts = {}, 0, 0
for q in sorted(pages):
    for o in pages[q]["items"]:
        if o["id"] in orders:
            dups += 1
            if orders[o["id"]] != o: conflicts += 1; print("CONFLICT", orders[o["id"]], o)
        else: orders[o["id"]] = o
statuses = Counter(repr(o["status"]) for o in orders.values())
lo = datetime(2025,3,1,tzinfo=timezone.utc); hi = datetime(2025,6,1,tzinfo=timezone.utc)
def parse(s):
    dt = datetime.fromisoformat(s.replace("Z","+00:00"))
    if dt.tzinfo is None: log["naive_ts"] += 1; dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)
qual = [o for o in orders.values() if o["status"] == "shipped" and lo <= parse(o["placed_at"]) < hi]
custs = {}
for cid in sorted({o["customer_id"] for o in qual}):
    custs[cid] = get(f"/customers/{cid}")
missing = [c for c,v in custs.items() if v is None]
by = {"north":0,"south":0,"east":0,"west":0}
odd = Counter()
for o in qual:
    c = custs[o["customer_id"]]
    if c is None: continue
    if c["id"] != o["customer_id"]: odd["cust_id_mismatch"] += 1
    if not isinstance(c["discount_pct"], int): odd["discount_type_"+type(c["discount_pct"]).__name__] += 1
    if not isinstance(o["amount_cents"], int): odd["amount_type_"+type(o["amount_cents"]).__name__] += 1
    amt = Decimal(o["amount_cents"]) * (Decimal(100) - Decimal(c["discount_pct"])) / Decimal(100)
    by[c["region"]] += int(amt.quantize(Decimal(1), rounding=ROUND_HALF_UP))
res = {"total_cents": sum(by.values()), "order_count": len(qual), "duplicates_skipped": dups, "by_region": by}
print(json.dumps(res, indent=2))
print("pages", len(pages), "listings", sum(len(v["items"]) for v in pages.values()), "unique", len(orders))
print("statuses", statuses); print("log", log); print("odd", odd, "missing customers", missing, "conflicts", conflicts)
print("discounts", Counter(c["discount_pct"] for c in custs.values() if c))
print("regions", Counter(repr(c["region"]) for c in custs.values() if c))
print("offsets", Counter(o["placed_at"][19:] for o in orders.values()))
json.dump(res, open("/tmp/recon/result.json","w"), indent=2)
EOF
